from __future__ import annotations
import math, random
from typing import Iterable, List, Tuple

Circle = Tuple[float, float, float]


def _repair(xs, ys, rs, rounds=400):
    r = list(rs)
    n = len(r)
    for _ in range(rounds):
        worst = 0.0
        for i in range(n):
            lim = min(xs[i], 1.0 - xs[i], ys[i], 1.0 - ys[i])
            if r[i] > lim:
                if r[i] - lim > worst: worst = r[i] - lim
                r[i] = lim
        for i in range(n):
            for j in range(i + 1, n):
                d = math.hypot(xs[i] - xs[j], ys[i] - ys[j])
                t = r[i] + r[j] - d
                if t > 0.0:
                    if t > worst: worst = t
                    h = 0.5 * t
                    r[i] -= h
                    r[j] -= h
        if worst < 1e-14:
            break
    return [v if v > 0.0 else 0.0 for v in r]


def _grow(xs, ys, r0, orders):
    n = len(xs)
    w = [min(xs[i], 1.0 - xs[i], ys[i], 1.0 - ys[i]) for i in range(n)]
    best = None
    for order in orders:
        r = [min(max(v, 0.0), w[i]) for i, v in enumerate(r0)]
        for _ in range(400):
            changed = False
            for i in order:
                m = w[i]
                xi = xs[i]; yi = ys[i]
                for j in range(n):
                    if j == i:
                        continue
                    v = math.hypot(xi - xs[j], yi - ys[j]) - r[j]
                    if v < m: m = v
                if m > r[i] + 1e-14:
                    r[i] = m
                    changed = True
            if not changed:
                break
        s = sum(r)
        if best is None or s > best[0]:
            best = (s, r)
    return best[1], best[0]


def _adam(xs, ys, rs, steps, mu0, mu1, lr0, lr1):
    n = len(xs)
    m = [0.0] * (3 * n); v = [0.0] * (3 * n)
    b1, b2, eps = 0.9, 0.999, 1e-8
    for t in range(1, steps + 1):
        fr = t / steps
        mu = mu0 * (mu1 / mu0) ** fr
        lr = lr0 * (lr1 / lr0) ** fr
        gx = [0.0] * n; gy = [0.0] * n; gr = [-1.0] * n
        for i in range(n):
            ri = rs[i]; xi = xs[i]; yi = ys[i]
            for val, ax, sg in ((xi, 0, -1.0), (1.0 - xi, 0, 1.0), (yi, 1, -1.0), (1.0 - yi, 1, 1.0)):
                d = ri - val
                if d > 0.0:
                    c = 2.0 * mu * d
                    gr[i] += c
                    if ax == 0: gx[i] += sg * c
                    else: gy[i] += sg * c
            for j in range(i + 1, n):
                dx = xi - xs[j]; dy = yi - ys[j]
                d = math.hypot(dx, dy)
                if d < 1e-9: d = 1e-9
                o = ri + rs[j] - d
                if o > 0.0:
                    c = 2.0 * mu * o / d
                    gx[i] -= c * dx; gy[i] -= c * dy
                    gx[j] += c * dx; gy[j] += c * dy
                    gr[i] += 2.0 * mu * o; gr[j] += 2.0 * mu * o
        g = gx + gy + gr
        idx = 0
        for p in (xs, ys, rs):
            for i in range(n):
                gi = g[idx]
                m[idx] = b1 * m[idx] + (1 - b1) * gi
                v[idx] = b2 * v[idx] + (1 - b2) * gi * gi
                mh = m[idx] / (1 - b1 ** t); vh = v[idx] / (1 - b2 ** t)
                p[i] -= lr * mh / (math.sqrt(vh) + eps)
                idx += 1
    return xs, ys, rs


def _seed(n, kind, rng):
    xs, ys = [], []
    if kind == 0:
        k = int(math.ceil(math.sqrt(n)))
        cells = [(i, j) for i in range(k) for j in range(k)]
        rng.shuffle(cells)
        for (i, j) in cells[:n]:
            xs.append(min(max((i + 0.5) / k + rng.uniform(-0.15, 0.15) / k, 0.01), 0.99))
            ys.append(min(max((j + 0.5) / k + rng.uniform(-0.15, 0.15) / k, 0.01), 0.99))
    else:
        pts = []
        k = int(math.ceil(math.sqrt(n)))
        for row in range(k + 1):
            cols = k + (row % 2)
            for ci in range(cols):
                pts.append((min(max((ci + 0.5 + 0.5 * (row % 2)) / (k + 0.6), 0.01), 0.99),
                            min(max((row + 0.5) / (k + 0.4), 0.01), 0.99)))
        rng.shuffle(pts)
        for p in pts[:n]:
            xs.append(p[0]); ys.append(p[1])
        while len(xs) < n:
            xs.append(rng.uniform(0.1, 0.9)); ys.append(rng.uniform(0.1, 0.9))
    return xs, ys


def generic(n, verbose=False):
    rng = random.Random(20240921 + n)
    if n > 100:
        k = int(math.ceil(math.sqrt(n)))
        r = 0.5 / k
        xs, ys = [], []
        cells = [(i, j) for i in range(k) for j in range(k)]
        for (i, j) in cells[:n]:
            xs.append(r + 2 * r * i); ys.append(r + 2 * r * j)
        return list(zip(xs, ys, [r] * n))
    steps = max(1500, min(6000, int(120000 / n)))
    best = None
    for trial in range(3):
        xs, ys = _seed(n, trial % 2, rng)
        rs = [0.02] * n
        mu1 = 10.0 ** (4.7 + 0.5 * trial)
        xs, ys, rs = _adam(xs, ys, rs, steps, 10.0, mu1, 0.01, 3e-5)
        r = _repair(xs, ys, rs)
        orders = [list(range(n)), list(range(n - 1, -1, -1))]
        r, s = _grow(xs, ys, r, orders)
        if best is None or s > best[0]:
            best = (s, xs, ys, r)
    s, xs, ys, r = best
    eps = 1e-9
    return [(xs[i], ys[i], max(0.0, r[i] - eps)) for i in range(n)]


def check(circles):
    n = len(circles)
    for (x, y, r) in circles:
        if r < 0 or x - r < -1e-9 or x + r > 1 + 1e-9 or y - r < -1e-9 or y + r > 1 + 1e-9:
            return "wall violation", (x, y, r)
    for i in range(n):
        for j in range(i + 1, n):
            d = math.hypot(circles[i][0] - circles[j][0], circles[i][1] - circles[j][1])
            if d < circles[i][2] + circles[j][2] - 1e-9:
                return "overlap", (i, j, d - circles[i][2] - circles[j][2])
    return None


if __name__ == "__main__":
    import time
    for n in [2, 3, 4, 5, 7, 9, 13, 16, 20, 26, 30, 40, 55, 70, 100, 144]:
        t0 = time.time()
        c = generic(n)
        dt = time.time() - t0
        bad = check(c)
        print("n=%3d sum=%.4f time=%.2fs bad=%s" % (n, sum(x[2] for x in c), dt, bad))
